const news = $('1. Read News Feed').all().map(item => item.json);
const inbox = $('2. Read Inbox').all().map(item => item.json);

return [{
  json: {
    news_feed: news,
    inbox
  }
}];

const evidence = $('4. Prepare Evidence for OpenAI').first()?.json ?? {};
const inboxItems = Array.isArray(evidence.inbox) ? evidence.inbox : [];

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;

  const s = value.trim();
  if (!s) return value;

  try {
    return JSON.parse(s);
  } catch {
    return value;
  }
}

function collectEmails(value) {
  value = parseMaybeJson(value);

  if (Array.isArray(value)) {
    return value.flatMap(collectEmails);
  }

  if (!value || typeof value !== 'object') {
    return [];
  }

  // Handle common inbox response structures.
  for (const key of ['emails', 'messages', 'inbox', 'items', 'results']) {
    if (Array.isArray(value[key])) {
      return value[key].flatMap(collectEmails);
    }
  }

  // Handle nested API response structures.
  for (const key of ['body', 'data', 'result']) {
    if (value[key] !== undefined) {
      const nested = collectEmails(value[key]);
      if (nested.length) return nested;
    }
  }

  // Recognize email records, including the simulator's from_address field.
  if (
    value.email_id ||
    value.message_id ||
    value.sender ||
    value.from ||
    value.from_email ||
    value.sender_email ||
    value.from_address
  ) {
    return [value];
  }

  return [];
}

// Known supplier domains are candidate mappings only.
// Actual verification happens later using Get Supplier Profile.
const trustedDomains = {
  'apex-mfg.com': 'S01',
  'lotus-comp.com': 'S02',
  'meridian-comp.com': 'S03',
  'orion-ind.com': 'S04',
  'zenith-mfg.com': 'S05',
  'harbor-comp.com': 'S06',
  'crestline-comp.com': 'S07',
  'nova-comp.com': 'S08',
  'sterling-comp.com': 'S09',
  'pacifica-tech.com': 'S10',
  'vertex-tech.com': 'S11',
  'summit-ind.com': 'S12',
  'bluewater-comp.com': 'S13',
  'kestrel-mfg.com': 'S14',
  'ironwood-mfg.com': 'S15',
  'polaris-ind.com': 'S16',
  'redwood-tech.com': 'S17',
  'solace-ind.com': 'S18',
  'tidewater-tech.com': 'S19',
  'unity-tech.com': 'S20',
  'granite-ind.com': 'S21',
  'halcyon-tech.com': 'S22',
  'juniper-tech.com': 'S23',
  'keystone-tech.com': 'S24',
  'lumen-ind.com': 'S25',
  'mosaic-tech.com': 'S26',
  'northstar-mfg.com': 'S27',
  'opal-mfg.com': 'S28',
  'quartz-ind.com': 'S29',
  'riverbend-mfg.com': 'S30',
  'saffron-ind.com': 'S31',
  'trident-ind.com': 'S32',
  'valiant-mfg.com': 'S33',
  'willow-comp.com': 'S34',
  'yarrow-tech.com': 'S35'
};

const emails = inboxItems.flatMap(collectEmails);

if (!emails.length) {
  return [{
    json: {
      no_emails: true,
      email_id: null,
      sender: '',
      sender_domain: '',
      supplier_id: null,
      supplier_verified: false,
      verification_status: 'not_checked',
      email: {}
    }
  }];
}

return emails.map(email => {
  // Support the simulator's actual sender field: from_address.
  let sender =
    email.from_email ??
    email.sender_email ??
    email.from_address ??
    email.sender ??
    email.from ??
    '';

  // Support sender fields returned as objects.
  if (sender && typeof sender === 'object') {
    sender = sender.email ?? sender.address ?? '';
  }

  sender = String(sender).trim();

  // Normalize the sender domain.
  const senderDomain = sender.includes('@')
    ? sender.split('@').pop().toLowerCase().trim()
    : '';

  // Map the domain to a candidate supplier.
  const supplierId = trustedDomains[senderDomain] ?? null;

  return {
    json: {
      email_id:
        email.email_id ??
        email.message_id ??
        email.id ??
        null,

      sender,
      sender_domain: senderDomain,
      supplier_id: supplierId,

      // Never assume identity is verified at this stage.
      supplier_verified: false,
      verification_status: 'not_checked',

      email
    }
  };
});

const candidate = $('6A. Filter Known Supplier Candidates').item.json;

function unwrap(value) {
  let current = value;
  for (let i = 0; i < 5; i++) {
    if (typeof current === 'string') {
      try { current = JSON.parse(current); } catch { break; }
    }
    if (!current || typeof current !== 'object') break;
    if (current.email_domain || current.registered_email_domain ||
        current.supplier_id) break;
    if (current.body !== undefined) { current = current.body; continue; }
    if (current.data !== undefined) { current = current.data; continue; }
    if (current.result !== undefined) { current = current.result; continue; }
    break;
  }
  return current && typeof current === 'object' ? current : {};
}

const profile = unwrap($json);
const senderDomain = String(candidate.sender_domain ?? '').toLowerCase().trim();
const registeredDomain = String(
  profile.email_domain ?? profile.registered_email_domain ?? ''
).toLowerCase().trim();

const supplierIdMatches =
  String(profile.supplier_id ?? '') === String(candidate.supplier_id ?? '');

const domainMatches =
  senderDomain !== '' &&
  registeredDomain !== '' &&
  senderDomain === registeredDomain;

const profileHasError = Boolean(profile.error || profile.detail);

const verified = !profileHasError && supplierIdMatches && domainMatches;

return {
  json: {
    ...candidate,
    supplier_profile: profile,
    registered_email_domain: registeredDomain,
    supplier_verified: verified,
    verification_status: verified ? 'verified' : 'verification_failed'
  }
};

const supplierChecks = $input.all()
  .map(item => item.json)
  .filter(item => item && item._empty_branch !== true);

const evidence = $('4. Prepare Evidence for OpenAI').first()?.json ?? {};

// FIX: a failed tool call must not look like an empty inbox / empty news feed.
function readError(rows) {
  for (const row of (Array.isArray(rows) ? rows : [])) {
    const e = row?.error ?? row?.detail;
    if (e) {
      return String(typeof e === 'string' ? e : (e.message ?? JSON.stringify(e))).slice(0, 300);
    }
  }
  return null;
}

return [{
  json: {
    news_feed: evidence.news_feed ?? [],
    inbox: evidence.inbox ?? [],
    supplier_email_checks: supplierChecks,
    inbox_read_error: readError(evidence.inbox),
    news_read_error: readError(evidence.news_feed)
  }
}];

const response = $json;

function safeFallback(reason) {
  return {
    json: {
      has_verified_disruption: false,
      disruptions: [],
      suspicious_emails: [],
      verified_legitimate_emails: [],
      report: 'OpenAI analysis could not be trusted or completed: ' + reason,
      requires_human_review: true,
      analysis_error: reason,
      status: 'needs_human_review',
      llm_model: response.model ?? 'ai_agent'
    }
  };
}

// The AI Agent node returns its reply in "output".
let content =
  response.output ??
  response.choices?.[0]?.message?.content ??
  response.body?.choices?.[0]?.message?.content;

if (content && typeof content === 'object') content = JSON.stringify(content);

const refusal = response.choices?.[0]?.message?.refusal;

if (typeof content !== 'string' || !content.trim()) {
  return safeFallback(response.error?.message ?? (typeof response.error === 'string' ? response.error : null) ?? refusal ?? 'No analysis content returned.');
}

content = content
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '')
  .trim();

// Keep only the JSON object if the agent added any text around it.
const firstBrace = content.indexOf('{');
const lastBrace = content.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace > firstBrace) {
  content = content.slice(firstBrace, lastBrace + 1);
}

let result;
try {
  result = JSON.parse(content);
} catch (error) {
  return safeFallback('Invalid JSON: ' + error.message);
}

if (
  typeof result.has_verified_disruption !== 'boolean' ||
  !Array.isArray(result.disruptions) ||
  !Array.isArray(result.suspicious_emails) ||
  !Array.isArray(result.verified_legitimate_emails) ||
  typeof result.report !== 'string'
) {
  return safeFallback('Response does not match the required output structure.');
}

// The old strict schema guaranteed whole numbers. Keep that guarantee here.
for (const d of result.disruptions) {
  if (d && typeof d.delay_days === 'string' && /^\d+$/.test(d.delay_days.trim())) {
    d.delay_days = Number(d.delay_days.trim());
  }
}

return {
  json: {
    ...result,
    requires_human_review: false,
    llm_model: response.model ?? 'ai_agent',
    status: 'analysis_completed'
  }
};

const analysis = $input.first().json;
const evidence = $('11. Combine Evidence for OpenAI').first()?.json ?? {};
const supplierChecks = evidence.supplier_email_checks ?? [];

const verifiedEmails = supplierChecks.filter(x =>
  x && x.supplier_verified === true && x.email_id
);

const allEvidenceText = JSON.stringify({
  news_feed: evidence.news_feed ?? [],
  inbox: evidence.inbox ?? [],
  supplier_email_checks: supplierChecks
});

const knownSourceIds = new Set(
  [...allEvidenceText.matchAll(/\b(?:N|E)\d+\b/g)].map(m => m[0])
);

function emailText(row) {
  return JSON.stringify(row.email ?? row).toLowerCase();
}

function hasExplicitDelay(row, days) {
  const email = row.email ?? {};
  const numericFields = [
    email.delay_days, email.expected_delay_days, email.delay_in_days,
    row.delay_days, row.expected_delay_days
  ];
  if (numericFields.some(v => Number(v) === days)) return true;

  const t = emailText(row);
  const n = String(days);
  const contextual = new RegExp(
    '(?:delay(?:ed)?|postpon(?:ed|ement)|slipp(?:ed|age)|late|eta|arrival|shipment)[^\\n]{0,70}\\b' +
    n + '\\s*(?:calendar\\s+|business\\s+)?days?\\b|\\b' +
    n + '\\s*(?:calendar\\s+|business\\s+)?days?\\b[^\\n]{0,70}' +
    '(?:delay|delayed|postponed|slipped|late|eta|arrival|shipment)',
    'i'
  );
  return contextual.test(t);
}

const validDisruptions = [];
const rejectedDisruptions = [];

for (const d of (Array.isArray(analysis.disruptions) ? analysis.disruptions : [])) {
  const errors = [];

  const supplierId = String(d.supplier_id ?? '');
  if (!/^S\d{2}$/.test(supplierId)) {
    errors.push('Invalid supplier ID');
  }

  if (d.verified !== true) errors.push('Model did not mark disruption verified');

  const matchingVerifiedEmails = verifiedEmails.filter(
    row => String(row.supplier_id) === supplierId
  );

  if (!matchingVerifiedEmails.length) {
    errors.push('No email from this supplier passed registered-domain verification');
  }

  if (!Array.isArray(d.part_ids) || d.part_ids.length === 0) {
    errors.push('Missing part IDs');
  } else {
    for (const partId of d.part_ids) {
      if (!/^P\d{3}$/.test(String(partId))) {
        errors.push('Invalid part ID: ' + partId);
        continue;
      }

      const partSupported = matchingVerifiedEmails.some(row =>
        emailText(row).includes(String(partId).toLowerCase())
      );

      if (!partSupported) {
        errors.push('Part ' + partId + ' is not explicitly present in a verified supplier email');
      }
    }
  }

  if (!Number.isInteger(d.delay_days) || d.delay_days < 1 || d.delay_days > 365) {
    errors.push('Invalid delay duration');
  } else {
    const delaySupported = matchingVerifiedEmails.some(row =>
      hasExplicitDelay(row, d.delay_days)
    );
    if (!delaySupported) {
      errors.push('The claimed delay is not explicitly stated in a verified supplier email');
    }
  }

  if (!Array.isArray(d.source_ids) || d.source_ids.length === 0) {
    errors.push('Missing source IDs');
  } else {
    for (const id of d.source_ids) {
      if (!knownSourceIds.has(String(id))) {
        errors.push('Source ID not found in supplied evidence: ' + id);
      }
    }

    const citedVerifiedEmail = matchingVerifiedEmails.some(row =>
      d.source_ids.map(String).includes(String(row.email_id))
    );
    if (!citedVerifiedEmail) {
      errors.push('Source IDs do not cite a verified email from the claimed supplier');
    }
  }

  if (typeof d.assessment !== 'string' || !d.assessment.trim()) {
    errors.push('Missing assessment');
  }

  if (errors.length === 0 && analysis.has_verified_disruption === true) {
    validDisruptions.push(d);
  } else {
    if (errors.length === 0) errors.push('Top-level has_verified_disruption was false');
    rejectedDisruptions.push({ disruption: d, errors });
  }
}

const valid = validDisruptions.length > 0;

// FIX: report a failed inbox / news read instead of a quiet "no disruption".
const readProblems = [
  evidence.inbox_read_error ? 'inbox (' + evidence.inbox_read_error + ')' : null,
  evidence.news_read_error ? 'news feed (' + evidence.news_read_error + ')' : null
].filter(Boolean);
const readFailed = readProblems.length > 0;
const readWarning = readFailed
  ? 'WARNING: could not read ' + readProblems.join(' and ') +
    '. This is a tool failure, not an empty result. '
  : '';
return [{
  json: {
    has_verified_disruption: valid,
    disruptions: validDisruptions,
    rejected_disruptions: rejectedDisruptions,
    suspicious_emails: analysis.suspicious_emails ?? [],
    verified_legitimate_emails: analysis.verified_legitimate_emails ?? [],
    report: readWarning + (analysis.report ?? ''),
    requires_human_review: analysis.requires_human_review === true || rejectedDisruptions.length > 0 || readFailed,
    read_errors: readProblems,
    validation_passed: rejectedDisruptions.length === 0,
    status: valid ? 'verified_disruption_candidate' :
      ((analysis.requires_human_review === true || readFailed) ? 'needs_human_review' : 'no_verified_disruption')
  }
}];

const validated = $('14. Validate Evidence-Based Actions').first().json;
const disruptions = validated.disruptions ?? [];

if (disruptions.length === 0) {
  return [{
    json: {
      no_valid_disruptions: true,
      suspicious_emails_for_review: validated.suspicious_emails ?? [],
      verified_legitimate_emails: validated.verified_legitimate_emails ?? [],
      rejected_disruptions: validated.rejected_disruptions ?? [],
      requires_human_review: validated.requires_human_review === true,
      report: validated.report ?? ''
    }
  }];
}

return disruptions.map(d => ({
  json: {
    no_valid_disruptions: false,
    incident: d,
    tool_args: {
      source_ids: d.source_ids,
      supplier_ids: [d.supplier_id],
      part_ids: d.part_ids,
      expected_delay_days: d.delay_days,
      assessment: d.assessment
    }
  }
}));

const request = $('15. Build Flag Disruption Requests').item.json;
const response = $json ?? {};

const failed = Boolean(
  response.error ||
  response.detail ||
  (Number.isFinite(Number(response.statusCode)) && Number(response.statusCode) >= 400) ||
  response.success === false
);

return {
  json: {
    simulator_recorded: !failed,
    simulator_error: failed ? (response.error?.message ?? response.detail ?? JSON.stringify(response)) : null,
    disruption: request.incident,
    simulator_response: response
  }
};

const validated = $('14. Validate Evidence-Based Actions').first().json;

return [{
  json: {
    has_verified_disruption: false,
    disruptions: [],
    suspicious_emails: validated.suspicious_emails ?? [],
    verified_legitimate_emails: validated.verified_legitimate_emails ?? [],
    rejected_disruptions: validated.rejected_disruptions ?? [],
    requires_human_review: validated.requires_human_review === true,
    report: validated.report ||
      'No evidence-backed disruption passed validation.',
    status: validated.requires_human_review === true
      ? 'needs_human_review'
      : 'no_verified_disruption'
  }
}];

const results = $input.all().map(item => item.json);

// Result of the mark_suspicious calls made this cycle (empty if none were needed).
let suspiciousMarked = [];
try {
  suspiciousMarked = $('14e. Capture Mark Result').all().map(i => i.json);
} catch (e) {}

const validated = $('14. Validate Evidence-Based Actions').first().json;

const recorded = results.filter(item => item.simulator_recorded === true);
const failedRecords = results.filter(item => item.simulator_recorded === false);
const noDisruption = results.find(item =>
  item.status === 'no_verified_disruption' ||
  item.status === 'needs_human_review'
);

if (recorded.length > 0) {
  const disruptions = recorded.map(item => {
    const d = item.disruption ?? {};
    const response = item.simulator_response ?? {};

    return {
      incident_id: response.incident_id ?? response.flag_id ?? null,
      supplier_id: d.supplier_id,
      part_ids: d.part_ids,
      delay_days: d.delay_days,
      source_ids: d.source_ids,
      affected_po_ids: Array.isArray(d.affected_po_ids) ? d.affected_po_ids : [],
      verified: true,
      assessment: d.assessment
    };
  });

  return [{
    json: {
      has_verified_disruption: true,
      disruptions,
      suspicious_emails: validated.suspicious_emails ?? [],
      verified_legitimate_emails: validated.verified_legitimate_emails ?? [],
      rejected_disruptions: validated.rejected_disruptions ?? [],
      requires_human_review: validated.requires_human_review === true,
      report: validated.report ?? '',
      suspicious_emails_marked: suspiciousMarked,
      status: 'verified_disruption_recorded'
    }
  }];
}

return [{
  json: {
    has_verified_disruption: false,
    disruptions: [],
    suspicious_emails: noDisruption?.suspicious_emails ?? validated.suspicious_emails ?? [],
    verified_legitimate_emails:
      noDisruption?.verified_legitimate_emails ?? validated.verified_legitimate_emails ?? [],
    rejected_disruptions:
      noDisruption?.rejected_disruptions ?? validated.rejected_disruptions ?? [],
    requires_human_review:
      failedRecords.length > 0 ||
      (noDisruption?.requires_human_review ?? validated.requires_human_review === true),
    report: failedRecords.length > 0
      ? 'The simulator did not confirm the disruption record. Manual review is required.'
      : (noDisruption?.report ?? validated.report ?? 'No evidence-backed disruption was recorded.'),
    simulator_errors: failedRecords.map(item => item.simulator_error),
    suspicious_emails_marked: suspiciousMarked,
    status: failedRecords.length > 0
      ? 'needs_human_review'
      : (noDisruption?.status ?? 'no_verified_disruption')
  }
}];

const rows = $input.all().map(item => item.json);
const known = rows.filter(x => x && x.supplier_id && x.email_id);
if (!known.length) {
  return [{ json: { _empty_branch: true, branch: 'known_supplier_candidates' } }];
}
return known.map(x => ({ json: x }));

const rows = $input.all().map(item => item.json);
const unknown = rows.filter(x => x && (!x.supplier_id || !x.email_id));
if (!unknown.length) {
  return [{ json: { _empty_branch: true, branch: 'unknown_sender_checks' } }];
}
return unknown.map(x => ({
  json: {
    ...x,
    supplier_verified: false,
    verification_status: x.no_emails ? 'no_emails' : 'unverified_sender'
  }
}));

// Decides which emails to mark as suspicious in the simulator.
// The AI only suggests. An email is marked only when ALL of these hold:
//   1. the email ID really is in the inbox read this cycle
//   2. the sender did NOT pass registered-domain verification
//   3. the inbox does not already show it as marked
const validated = $input.first().json;
const evidence = $('11. Combine Evidence for OpenAI').first()?.json ?? {};
const checks = Array.isArray(evidence.supplier_email_checks)
  ? evidence.supplier_email_checks
  : [];

const byId = new Map(
  checks
    .filter(c => c && c.email_id)
    .map(c => [String(c.email_id), c])
);

const seen = new Set();
const requests = [];
const skipped = [];

for (const s of (Array.isArray(validated.suspicious_emails) ? validated.suspicious_emails : [])) {
  const id = String(s?.email_id ?? '').trim();
  if (!id || seen.has(id)) continue;
  seen.add(id);

  const check = byId.get(id);

  if (!check) {
    skipped.push({ email_id: id, why: 'Email ID is not in the inbox read this cycle.' });
    continue;
  }

  if (check.supplier_verified === true) {
    skipped.push({ email_id: id, why: 'Sender passed registered-domain verification. Left for human review.' });
    continue;
  }

  const e = check.email ?? {};
  if (e.suspicious === true || e.marked_suspicious === true || e.flagged_suspicious === true) {
    skipped.push({ email_id: id, why: 'Already marked as suspicious.' });
    continue;
  }

  requests.push({
    json: {
      skip: false,
      email_id: id,
      reason: String(s?.reason ?? '').replace(/\s+/g, ' ').trim().slice(0, 300) ||
        'Flagged as suspicious by the Disruption Detector.'
    }
  });
}

if (!requests.length) {
  return [{ json: { skip: true, skipped } }];
}

requests[0].json.skipped = skipped;
return requests;

// Records whether the simulator accepted each mark_suspicious call.
const requests = $('14b. Build Mark Suspicious Requests').all().map(i => i.json);

return $input.all().map((item, index) => {
  const r = item.json ?? {};

  const failed = Boolean(
    r.error ||
    r.detail ||
    r.success === false ||
    (Number.isFinite(Number(r.statusCode)) && Number(r.statusCode) >= 400)
  );

  const problem = r.error?.message ?? r.error ?? r.detail ?? r;

  return {
    json: {
      email_id: requests[index]?.email_id ?? null,
      reason: requests[index]?.reason ?? null,
      marked: !failed,
      error: failed
        ? String(typeof problem === 'string' ? problem : JSON.stringify(problem)).slice(0, 300)
        : null
    }
  };
});
